"""Tests for the Edge model."""

from __future__ import annotations

from dataclasses import FrozenInstanceError

import pytest

from depcycle.graph.edge import Edge
from depcycle.graph.node import Node


def test_edge_creation_and_repr() -> None:
    """Test creating an edge and checking its representation."""
    source = Node(name="source_mod")
    target = Node(name="target_mod")

    edge = Edge(source=source, target=target)

    assert edge.source is source
    assert edge.target is target
    assert repr(edge) == "Edge('source_mod' -> 'target_mod')"


def test_edge_immutability() -> None:
    """Test that Edge is frozen and prevents attribute modification."""
    source = Node(name="a")
    target = Node(name="b")
    replacement = Node(name="c")

    edge = Edge(source=source, target=target)

    with pytest.raises(FrozenInstanceError):
        edge.target = replacement  # type: ignore[misc]


def test_equal_edges_are_deduplicated() -> None:
    """Test dataclass equality and set behavior for identical edges."""
    source = Node(name="source")
    target = Node(name="target")

    edge_a = Edge(source=source, target=target)
    edge_b = Edge(source=Node(name="source"), target=Node(name="target"))

    assert edge_a == edge_b
    assert len({edge_a, edge_b}) == 1
